<script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import api from'../services/api.js';import GuideCard from'../components/GuideCard.vue';import SectionTitle from'../components/SectionTitle.vue';const route=useRoute(),data=ref(null);onMounted(async()=>data.value=await api.get(`/public/topics/${route.params.id}`))</script>
<template><div v-if="!data" class="loading-panel"><el-skeleton :rows="10" animated/></div><div v-else><section class="topic-hero" :style="{backgroundImage:`linear-gradient(90deg,rgba(8,41,48,.82),rgba(8,41,48,.1)),url(${data.coverImage})`}"><div class="container"><span>CURATED BY 山海迹</span><h1>{{data.name}}</h1><p>{{data.subtitle}}</p></div></section><section class="section"><div class="container intro"><div><span class="eyebrow">ABOUT THIS COLLECTION</span><h2>{{data.summary}}</h2></div><p>{{data.content}}</p></div></section><section class="section soft"><div class="container"><SectionTitle eyebrow="SELECTED STORIES" title="专题精选攻略" subtitle="从具体的路线、预算和在地经验开始规划"/><div class="guide-grid"><GuideCard v-for="guide in data.guides" :key="guide.id" :guide="guide"/></div></div></section></div></template>
